syntax:
void function_name(element_type *array_param, size_t size); // or
void function_name(element_type array_param[], size_t size); // array parameter decays to pointer

// Inside the function, 'array_param' is treated as a pointer to the first element
// No automatic size information is available; size must be passed explicitly if needed.

code_example:
void process_array(int arr[], size_t n) {
    for (size_t i = 0; i < n; ++i) {
        arr[i] = arr[i] * 2; // modifies original array via pointer decay
    }
}
int main() {
    int data[5] = {1, 2, 3, 4, 5};
    process_array(data, 5); // 'data' decays to pointer, size passed explicitly
    return 0;
}
